window.SCERE_CRYPTO_SVGS = Object.assign(window.SCERE_CRYPTO_SVGS || {}, {
  "crypto-04-1-attention-follows-price": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">New Users Arrive After the Price Rises</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">Bank for International Settlements Working Paper 1049: retail exchange app use across 95 countries, 2015 to 2022.</text>\n  <line x1=\"90\" y1=\"100\" x2=\"750\" y2=\"100\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"104\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <line x1=\"90\" y1=\"157.5\" x2=\"750\" y2=\"157.5\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"161.5\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <line x1=\"90\" y1=\"215\" x2=\"750\" y2=\"215\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"219\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <line x1=\"90\" y1=\"272.5\" x2=\"750\" y2=\"272.5\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"3 5\"/>\n  <text x=\"80\" y=\"276.5\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <line x1=\"90\" y1=\"330\" x2=\"750\" y2=\"330\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"334\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"90\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"172.5\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"255\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"337.5\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"420\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"502.5\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"585\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"667.5\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <text x=\"750\" y=\"352\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\"></text>\n  <polyline points=\"90.0,304.4 172.5,294.2 255.0,273.8 337.5,212.4 420.0,130.7 502.5,171.6 585.0,227.8 667.5,253.3 750.0,263.6\" fill=\"none\" stroke=\"var(--info-500)\" stroke-width=\"3\"/>\n  <text x=\"758\" y=\"267.55555555555554\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--info-text)\" font-weight=\"bold\">price</text>\n  <polyline points=\"90.0,314.7 172.5,312.1 255.0,304.4 337.5,284.0 420.0,217.6 502.5,151.1 585.0,197.1 667.5,243.1 750.0,273.8\" fill=\"none\" stroke=\"var(--warning-500)\" stroke-width=\"3\"/>\n  <text x=\"758\" y=\"344\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">new users</text>\n  <text x=\"420\" y=\"356\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">time</text>\n  <line x1=\"430\" y1=\"100\" x2=\"430\" y2=\"330\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"438\" y=\"118\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--info-text)\" font-weight=\"bold\">price peaks here</text>\n  <line x1=\"505\" y1=\"100\" x2=\"505\" y2=\"330\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"513\" y=\"138\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">arrivals peak here</text>\n  <rect x=\"60\" y=\"380\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"406\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-text)\" font-weight=\"bold\">What the study found</text>\n  <text x=\"76\" y=\"434\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">An estimated 73 to 81% of retail investors had</text>\n  <text x=\"76\" y=\"452\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">likely lost money on their initial investment.</text>\n  <text x=\"76\" y=\"478\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">About three quarters of new investors downloaded</text>\n  <text x=\"76\" y=\"496\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">an app after Bitcoin passed 20,000 dollars.</text>\n  <text x=\"76\" y=\"518\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">When prices rose, the largest holders were selling.</text>\n  <rect x=\"460\" y=\"380\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"406\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--success-text)\" font-weight=\"bold\">Why the lag is structural</text>\n  <text x=\"476\" y=\"434\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Nobody writes an article about an asset that has</text>\n  <text x=\"476\" y=\"452\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">done nothing. Coverage, group chats and adverts</text>\n  <text x=\"476\" y=\"470\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">are all downstream of a rise that has happened.</text>\n  <text x=\"476\" y=\"496\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">So the ordinary experience of hearing about</text>\n  <text x=\"476\" y=\"514\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">crypto is the experience of hearing about it late.</text>\n</svg>",
  "crypto-04-2-scam-markers": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Six Structures, and the Markers That Catch Them</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">Almost everything you will meet is one of these. Each has a marker you can check rather than a feeling you have to trust.</text>\n  <rect x=\"40\" y=\"86\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"155\" y=\"112\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-500)\" font-weight=\"bold\">Rug pull</text>\n  <text x=\"54\" y=\"134\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">Liquidity withdrawn or holdings</text>\n  <text x=\"54\" y=\"148\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">dumped after promotion. Roughly half</text>\n  <text x=\"54\" y=\"162\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">of Uniswap listings, per Xia and</text>\n  <text x=\"54\" y=\"176\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">colleagues 2021.</text>\n  <rect x=\"290\" y=\"86\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"405\" y=\"112\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-500)\" font-weight=\"bold\">Yield scheme</text>\n  <text x=\"304\" y=\"134\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">A fixed high return funded by later</text>\n  <text x=\"304\" y=\"148\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">deposits rather than by any</text>\n  <text x=\"304\" y=\"162\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">activity.</text>\n  <rect x=\"40\" y=\"196\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"155\" y=\"222\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--warning-500)\" font-weight=\"bold\">Pig butchering</text>\n  <text x=\"54\" y=\"244\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">A relationship built first, a fake</text>\n  <text x=\"54\" y=\"258\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">platform introduced later.</text>\n  <rect x=\"290\" y=\"196\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"405\" y=\"222\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--warning-500)\" font-weight=\"bold\">Withdrawal-fee scam</text>\n  <text x=\"304\" y=\"244\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">Outside money demanded before a</text>\n  <text x=\"304\" y=\"258\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">balance is released.</text>\n  <rect x=\"40\" y=\"306\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--info-500)\" stroke-width=\"2\"/>\n  <text x=\"155\" y=\"332\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--info-500)\" font-weight=\"bold\">Approval draining</text>\n  <text x=\"54\" y=\"354\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">A permission signed earlier, used to</text>\n  <text x=\"54\" y=\"368\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">remove funds later.</text>\n  <rect x=\"290\" y=\"306\" width=\"230\" height=\"96\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--info-500)\" stroke-width=\"2\"/>\n  <text x=\"405\" y=\"332\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--info-500)\" font-weight=\"bold\">Impersonation</text>\n  <text x=\"304\" y=\"354\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">A known person, project or support</text>\n  <text x=\"304\" y=\"368\" text-anchor=\"start\" font-size=\"11\" fill=\"var(--diagram-muted)\">channel imitated.</text>\n  <rect x=\"556\" y=\"86\" width=\"304\" height=\"316\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"708\" y=\"112\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--success-text)\" font-weight=\"bold\">Markers that work on structures</text>\n  <text x=\"708\" y=\"130\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--success-text)\" font-weight=\"bold\">nobody has invented yet</text>\n  <text x=\"572\" y=\"162\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">A guaranteed return on a volatile asset</text>\n  <text x=\"572\" y=\"192\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">An unexplained source of yield</text>\n  <text x=\"572\" y=\"222\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">Contact you did not initiate</text>\n  <text x=\"572\" y=\"252\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">Pressure to act before a deadline</text>\n  <text x=\"572\" y=\"282\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">A referral component in the returns</text>\n  <text x=\"572\" y=\"312\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">Friction that appears only on withdrawal</text>\n  <text x=\"572\" y=\"342\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\">Any request for a recovery phrase</text>\n  <rect x=\"40\" y=\"418\" width=\"820\" height=\"112\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"444\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">Not on that list, because all of it is cheap to fabricate</text>\n  <text x=\"450\" y=\"470\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">How professional the website looks. Whether there is a whitepaper. Whether well-known names appear as advisers.</text>\n  <text x=\"450\" y=\"490\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Whether an audit exists, which reviews code at a point in time and does not establish that the design is safe.</text>\n  <text x=\"450\" y=\"514\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">And whether other people you know are already in, which is how these schemes grow rather than evidence they are sound.</text>\n</svg>",
  "crypto-04-3-custody-plan": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Seven Sections of a Crypto Plan</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">Four that any trading plan needs, and three that only an asset you can hold yourself requires.</text>\n  <circle cx=\"72\" cy=\"104\" r=\"18\" fill=\"var(--info-500)\"/>\n  <text x=\"72\" y=\"109\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">1</text>\n  <text x=\"104\" y=\"100\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Allocation</text>\n  <text x=\"104\" y=\"122\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">How much of total wealth is in this asset class at all, decided before looking at any token.</text>\n  <circle cx=\"72\" cy=\"162\" r=\"18\" fill=\"var(--info-500)\"/>\n  <text x=\"72\" y=\"167\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">2</text>\n  <text x=\"104\" y=\"158\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Position sizing</text>\n  <text x=\"104\" y=\"180\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">The Chapter 3 Lesson 1 formula at crypto volatility, written as a number rather than a principle.</text>\n  <circle cx=\"72\" cy=\"220\" r=\"18\" fill=\"var(--info-500)\"/>\n  <text x=\"72\" y=\"225\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">3</text>\n  <text x=\"104\" y=\"216\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Leverage</text>\n  <text x=\"104\" y=\"238\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">For most readers a single word: none. Otherwise a maximum and the liquidation price, in advance.</text>\n  <circle cx=\"72\" cy=\"278\" r=\"18\" fill=\"var(--info-500)\"/>\n  <text x=\"72\" y=\"283\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">4</text>\n  <text x=\"104\" y=\"274\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Entry and exit conditions</text>\n  <text x=\"104\" y=\"296\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">What has to be true to buy, and what has to be true to sell. Chapter 6 fills this properly.</text>\n  <circle cx=\"72\" cy=\"336\" r=\"18\" fill=\"var(--warning-500)\"/>\n  <text x=\"72\" y=\"341\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">5</text>\n  <text x=\"104\" y=\"332\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Custody map</text>\n  <text x=\"104\" y=\"354\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">How much stays on an exchange, and the amount above which holdings move to self-custody.</text>\n  <circle cx=\"72\" cy=\"394\" r=\"18\" fill=\"var(--warning-500)\"/>\n  <text x=\"72\" y=\"399\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">6</text>\n  <text x=\"104\" y=\"390\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Recovery plan</text>\n  <text x=\"104\" y=\"412\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Where the phrase is, how many copies exist, and what happens to them in a fire or a flood.</text>\n  <circle cx=\"72\" cy=\"452\" r=\"18\" fill=\"var(--warning-500)\"/>\n  <text x=\"72\" y=\"457\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">7</text>\n  <text x=\"104\" y=\"448\" text-anchor=\"start\" font-size=\"15\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Succession</text>\n  <text x=\"104\" y=\"470\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Who else knows this exists, and what happens to it if you do not.</text>\n  <line x1=\"60\" y1=\"508\" x2=\"840\" y2=\"508\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"534\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">The last three exist because self-custody moves the failure mode from a counterparty to you.</text>\n</svg>",
  "crypto-05-1-mt-gox-timeline": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Mt. Gox: Three Weeks of Collapse, Three Years of Loss</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">The theft ran undetected from 2011. What ended in February 2014 was the belief that the balance described anything real.</text>\n  <line x1=\"340\" y1=\"150\" x2=\"850\" y2=\"150\" stroke=\"var(--diagram-grid)\" stroke-width=\"2\"/>\n  <rect x=\"66\" y=\"118\" width=\"268\" height=\"62\" rx=\"6\" fill=\"var(--danger-500)\"/>\n  <text x=\"200\" y=\"144\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">2011 to 2013: theft running,</text>\n  <text x=\"200\" y=\"162\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-bg)\" font-weight=\"bold\">undetected the whole time</text>\n  <circle cx=\"430\" cy=\"150\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"430\" y=\"122\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">7 Feb 2014</text>\n  <text x=\"430\" y=\"178\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">withdrawals halted</text>\n  <circle cx=\"555\" cy=\"150\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"555\" y=\"122\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">28 Feb 2014</text>\n  <text x=\"555\" y=\"224\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">Tokyo filing: 850,000</text>\n  <text x=\"555\" y=\"239\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">BTC lost, 750,000 of</text>\n  <text x=\"555\" y=\"254\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">it customers</text>\n  <circle cx=\"675\" cy=\"150\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"675\" y=\"122\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">9 Mar 2014</text>\n  <text x=\"675\" y=\"178\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">United States filing</text>\n  <circle cx=\"790\" cy=\"150\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"790\" y=\"122\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">20 Mar 2014</text>\n  <text x=\"790\" y=\"224\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">about 200,000 BTC</text>\n  <text x=\"790\" y=\"239\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">found in a wallet last</text>\n  <text x=\"790\" y=\"254\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">used before June 2011</text>\n  <rect x=\"60\" y=\"290\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"316\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-text)\" font-weight=\"bold\">The exchange did not know what it held</text>\n  <text x=\"76\" y=\"344\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">An exchange holding hundreds of thousands of</text>\n  <text x=\"76\" y=\"362\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">customer bitcoin found 200,000 of them in a wallet</text>\n  <text x=\"76\" y=\"380\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">nobody had checked in three years.</text>\n  <text x=\"76\" y=\"406\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">That is not a sophisticated attack. It is the absence</text>\n  <text x=\"76\" y=\"424\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">of the most basic control in custody.</text>\n  <rect x=\"460\" y=\"290\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"316\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--success-text)\" font-weight=\"bold\">The defence that needed no foresight</text>\n  <text x=\"476\" y=\"344\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">A user with 20 BTC who kept 2 on the exchange</text>\n  <text x=\"476\" y=\"362\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">and 18 in self-custody lost 10% and kept 90%.</text>\n  <text x=\"476\" y=\"388\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">A user with all 20 on the exchange lost everything.</text>\n  <text x=\"476\" y=\"414\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Neither knew anything the other did not. One had</text>\n  <text x=\"476\" y=\"432\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">a custody rule and the other had a habit.</text>\n  <text x=\"450\" y=\"474\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">The malleability explanation the exchange offered was checked against the public ledger and did not survive.</text>\n  <text x=\"450\" y=\"498\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Decker and Wattenhofer, 2014: attacks existed but were nowhere near large enough to account for 750,000 coins.</text>\n  <text x=\"450\" y=\"522\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Repayments to creditors began in July 2024, slightly over ten years later.</text>\n</svg>",
  "crypto-05-2-terra-spiral": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Terra and Luna: A Mechanism Executing Correctly, All the Way Down</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">UST fell below one dollar on 7 May 2022. By 13 May, LUNA had gone from about 87 dollars to below 0.00005.</text>\n  <rect x=\"40\" y=\"96\" width=\"180\" height=\"76\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"130\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-500)\" font-weight=\"bold\">UST trades below one</text>\n  <text x=\"130\" y=\"142\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-500)\" font-weight=\"bold\">dollar</text>\n  <rect x=\"250\" y=\"96\" width=\"180\" height=\"76\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"340\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-500)\" font-weight=\"bold\">Holders redeem it for</text>\n  <text x=\"340\" y=\"142\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-500)\" font-weight=\"bold\">newly minted LUNA</text>\n  <rect x=\"460\" y=\"96\" width=\"180\" height=\"76\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"550\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--danger-500)\" font-weight=\"bold\">That LUNA is sold</text>\n  <rect x=\"640\" y=\"96\" width=\"180\" height=\"76\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"730\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--danger-500)\" font-weight=\"bold\">The LUNA price falls</text>\n  <text x=\"235\" y=\"138\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">so</text>\n  <text x=\"445\" y=\"138\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">and</text>\n  <text x=\"640\" y=\"138\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">so</text>\n  <line x1=\"730\" y1=\"172\" x2=\"730\" y2=\"200\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <line x1=\"130\" y1=\"200\" x2=\"730\" y2=\"200\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <line x1=\"130\" y1=\"172\" x2=\"130\" y2=\"200\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"430\" y=\"220\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--danger-text)\" font-weight=\"bold\">so each further redemption needs more LUNA minted, and the loop tightens</text>\n  <rect x=\"60\" y=\"244\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"270\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--warning-text)\" font-weight=\"bold\">Where the 20% yield came from</text>\n  <text x=\"76\" y=\"298\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Anchor paid roughly 20% a year on UST deposits,</text>\n  <text x=\"76\" y=\"316\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">and close to 75% of all UST sat in it.</text>\n  <text x=\"76\" y=\"342\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">On about 14 billion dollars that is roughly 2.8</text>\n  <text x=\"76\" y=\"360\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">billion a year, paid out of a reserve.</text>\n  <text x=\"76\" y=\"384\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">A rate paid from capital, not from an activity.</text>\n  <rect x=\"460\" y=\"244\" width=\"380\" height=\"150\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"270\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-text)\" font-weight=\"bold\">The defence, and what it cost everyone else</text>\n  <text x=\"476\" y=\"298\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">A reserve of about 80,394 bitcoin was deployed</text>\n  <text x=\"476\" y=\"316\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">between roughly 8 and 12 May. By 16 May about</text>\n  <text x=\"476\" y=\"334\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">313 remained. The peg was not restored.</text>\n  <text x=\"476\" y=\"360\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">The selling pushed Bitcoin from around 39,000</text>\n  <text x=\"476\" y=\"378\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">to around 28,000 that week. That is contagion.</text>\n  <line x1=\"60\" y1=\"416\" x2=\"840\" y2=\"416\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"444\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">The mechanism was not defeated by a bug or an attack. Every redemption did exactly what the documentation said.</text>\n  <text x=\"450\" y=\"470\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">UST needed LUNA to be valuable; LUNA was valuable because it underpinned UST. Neither was anchored outside the pair.</text>\n  <text x=\"450\" y=\"496\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">LUNA fell about 99.99994%. Returning to 87 dollars from there would require a rise of roughly 1,740,000 times.</text>\n  <text x=\"450\" y=\"522\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--warning-text)\" font-weight=\"bold\">A system can be functioning perfectly and be catastrophic. Those are not contradictory statements.</text>\n</svg>",
  "crypto-05-3-ftx-run": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">FTX: Nine Days From a Published Balance Sheet to Bankruptcy</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">The venue widely regarded as the responsible one. Every credibility signal pointed the right way.</text>\n  <line x1=\"70\" y1=\"140\" x2=\"830\" y2=\"140\" stroke=\"var(--diagram-grid)\" stroke-width=\"2\"/>\n  <circle cx=\"110\" cy=\"140\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"110\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">2 Nov</text>\n  <text x=\"110\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">CoinDesk publishes the</text>\n  <text x=\"110\" y=\"183\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">Alameda balance sheet</text>\n  <circle cx=\"280\" cy=\"140\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"280\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">6 Nov</text>\n  <text x=\"280\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">Binance announces it</text>\n  <text x=\"280\" y=\"183\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">will sell its FTT</text>\n  <circle cx=\"480\" cy=\"140\" r=\"6\" fill=\"var(--warning-500)\"/>\n  <text x=\"480\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">8 to 9 Nov</text>\n  <text x=\"480\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">Binance offers to buy</text>\n  <text x=\"480\" y=\"183\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">FTX, then withdraws</text>\n  <circle cx=\"700\" cy=\"140\" r=\"6\" fill=\"var(--danger-500)\"/>\n  <text x=\"700\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--danger-text)\" font-weight=\"bold\">11 Nov</text>\n  <text x=\"700\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--diagram-muted)\">Chapter 11 filing</text>\n  <text x=\"420\" y=\"224\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">roughly 5 billion dollars of withdrawal requests arrived within about 72 hours</text>\n  <text x=\"318\" y=\"278\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">liabilities</text>\n  <rect x=\"330\" y=\"256\" width=\"380\" height=\"34\" rx=\"3\" fill=\"var(--danger-500)\"/>\n  <text x=\"720\" y=\"278\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--danger-text)\" font-weight=\"bold\">about 9 billion</text>\n  <text x=\"318\" y=\"330\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">assets that could readily be sold</text>\n  <rect x=\"330\" y=\"308\" width=\"38\" height=\"34\" rx=\"3\" fill=\"var(--success-500)\"/>\n  <text x=\"378\" y=\"330\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--success-text)\" font-weight=\"bold\">about 900 million</text>\n  <text x=\"450\" y=\"356\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--warning-text)\" font-weight=\"bold\">A shortfall of roughly 8 billion dollars</text>\n  <rect x=\"60\" y=\"370\" width=\"380\" height=\"152\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"396\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--danger-text)\" font-weight=\"bold\">Why judging the counterparty failed</text>\n  <text x=\"76\" y=\"424\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Prominent venture backing. Testimony before</text>\n  <text x=\"76\" y=\"442\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">legislators. Advertising at major sporting events.</text>\n  <text x=\"76\" y=\"460\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Withdrawals worked normally until they did not.</text>\n  <text x=\"76\" y=\"484\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Sophisticated institutions reached the same</text>\n  <rect x=\"460\" y=\"370\" width=\"380\" height=\"152\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"650\" y=\"396\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--success-text)\" font-weight=\"bold\">What actually worked</text>\n  <text x=\"476\" y=\"424\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Assets in self-custody were not less affected.</text>\n  <text x=\"476\" y=\"442\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">They were unaffected. The exchange failing had</text>\n  <text x=\"476\" y=\"460\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">no mechanism by which to reach them.</text>\n  <text x=\"476\" y=\"484\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">A user with 5,000 there and 45,000 in their own</text>\n  <text x=\"76\" y=\"502\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">wrong conclusion.</text>\n  <text x=\"476\" y=\"502\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-text)\" font-weight=\"bold\">wallet lost 10% and predicted nothing.</text>\n  <text x=\"450\" y=\"546\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Convicted on seven counts in November 2023; sentenced to 25 years in March 2024. That is justice, not restitution.</text>\n</svg>",
  "crypto-06-1-six-pillars": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">The Six Pillars, Adapted for an Asset With No Cash Flows</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">Four transfer, one is replaced by supply arithmetic, and one only resembles carry.</text>\n  <rect x=\"40\" y=\"90\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"114\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--warning-500)\" font-weight=\"bold\">Fundamentals</text>\n  <text x=\"58\" y=\"134\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">On-chain activity, with the Chapter 2 Lesson 4 limits. An address is not a person.</text>\n  <text x=\"842\" y=\"122\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--warning-500)\" font-weight=\"bold\">adapted</text>\n  <rect x=\"40\" y=\"152\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"176\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--danger-500)\" font-weight=\"bold\">Valuation</text>\n  <text x=\"58\" y=\"196\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Does not transfer. No cash flows means no calculation to compare a price against.</text>\n  <text x=\"842\" y=\"184\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--danger-500)\" font-weight=\"bold\">replaced</text>\n  <rect x=\"40\" y=\"214\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"238\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--success-500)\" font-weight=\"bold\">Catalyst</text>\n  <text x=\"58\" y=\"258\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Transfers well. But a date everyone can read has had as long as everyone to be priced.</text>\n  <text x=\"842\" y=\"246\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--success-500)\" font-weight=\"bold\">transfers</text>\n  <rect x=\"40\" y=\"276\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"300\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--success-500)\" font-weight=\"bold\">Positioning</text>\n  <text x=\"58\" y=\"320\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Stronger here than anywhere. Funding rates state directly when leverage is crowded.</text>\n  <text x=\"842\" y=\"308\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--success-500)\" font-weight=\"bold\">transfers</text>\n  <rect x=\"40\" y=\"338\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"362\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--success-500)\" font-weight=\"bold\">Momentum</text>\n  <text x=\"58\" y=\"382\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">One of the three factors in Liu, Tsyvinski and Wu 2022. Decays in weeks, not months.</text>\n  <text x=\"842\" y=\"370\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--success-500)\" font-weight=\"bold\">transfers</text>\n  <rect x=\"40\" y=\"400\" width=\"820\" height=\"54\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"58\" y=\"424\" text-anchor=\"start\" font-size=\"14\" fill=\"var(--warning-500)\" font-weight=\"bold\">Carry</text>\n  <text x=\"58\" y=\"444\" text-anchor=\"start\" font-size=\"12\" fill=\"var(--diagram-muted)\">Staking often pays in the falling token, funded by issuance that dilutes you.</text>\n  <text x=\"842\" y=\"432\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--warning-500)\" font-weight=\"bold\">qualified</text>\n  <line x1=\"60\" y1=\"474\" x2=\"840\" y2=\"474\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\"/>\n  <text x=\"450\" y=\"500\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Replacing valuation: total supply, the unlock schedule, and the market capitalisation a price target implies.</text>\n  <text x=\"450\" y=\"526\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Independence is the whole point. A price that has risen produces momentum, sentiment, funding and activity at once — one fact, four times.</text>\n</svg>",
  "crypto-06-2-transmission-chain": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Crypto Sits at the Far End of the Transmission Chain</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">Much of what looks like crypto news is a decision taken in a bond market weeks earlier, arriving amplified.</text>\n  <rect x=\"40\" y=\"96\" width=\"132\" height=\"84\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"106\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-500)\" font-weight=\"bold\">Interest rates</text>\n  <text x=\"106\" y=\"202\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">the policy change</text>\n  <text x=\"192\" y=\"143\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">then</text>\n  <rect x=\"212\" y=\"96\" width=\"132\" height=\"84\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"278\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-500)\" font-weight=\"bold\">Currencies and</text>\n  <text x=\"278\" y=\"140\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-500)\" font-weight=\"bold\">bonds</text>\n  <text x=\"278\" y=\"202\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">yields move first</text>\n  <text x=\"364\" y=\"143\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">then</text>\n  <rect x=\"384\" y=\"96\" width=\"132\" height=\"84\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--info-500)\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--info-500)\" font-weight=\"bold\">Credit</text>\n  <text x=\"450\" y=\"202\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">spreads widen</text>\n  <text x=\"536\" y=\"143\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">then</text>\n  <rect x=\"556\" y=\"96\" width=\"132\" height=\"84\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--info-500)\" stroke-width=\"2\"/>\n  <text x=\"622\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--info-500)\" font-weight=\"bold\">Equities</text>\n  <text x=\"622\" y=\"202\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">long duration falls</text>\n  <text x=\"622\" y=\"217\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">hardest</text>\n  <text x=\"708\" y=\"143\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">then</text>\n  <rect x=\"728\" y=\"96\" width=\"132\" height=\"84\" rx=\"8\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"794\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--danger-500)\" font-weight=\"bold\">Crypto</text>\n  <text x=\"794\" y=\"202\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">no cash flows at all</text>\n  <text x=\"450\" y=\"234\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Crypto has the longest duration of anything on this chain, so it receives the same change last and largest.</text>\n  <rect x=\"30\" y=\"256\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"162.66666666666666\" y=\"286\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--success-500)\" font-weight=\"bold\">Trending, risk-on</text>\n  <text x=\"46\" y=\"318\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Momentum has power.</text>\n  <text x=\"46\" y=\"345\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">Valuation-style arguments have</text>\n  <text x=\"46\" y=\"364\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">almost none, because nothing is</text>\n  <text x=\"46\" y=\"383\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">being valued.</text>\n  <text x=\"46\" y=\"420\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Funding climbs and leverage</text>\n  <text x=\"46\" y=\"439\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">accumulates.</text>\n  <rect x=\"317.3333333333333\" y=\"256\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--danger-500)\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"286\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--danger-500)\" font-weight=\"bold\">Stressed</text>\n  <text x=\"333.3333333333333\" y=\"318\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Positioning and leverage data have</text>\n  <text x=\"333.3333333333333\" y=\"337\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">power.</text>\n  <text x=\"333.3333333333333\" y=\"364\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">Narrative has none — narrative is</text>\n  <text x=\"333.3333333333333\" y=\"383\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">what is being liquidated.</text>\n  <text x=\"333.3333333333333\" y=\"420\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Correlations converge and</text>\n  <text x=\"333.3333333333333\" y=\"439\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">diversification stops working.</text>\n  <rect x=\"604.6666666666666\" y=\"256\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--diagram-muted)\" stroke-width=\"2\"/>\n  <text x=\"737.3333333333333\" y=\"286\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--diagram-muted)\" font-weight=\"bold\">Ranging</text>\n  <text x=\"620.6666666666666\" y=\"318\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Nothing much has power.</text>\n  <text x=\"620.6666666666666\" y=\"345\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">A 24-hour market manufactures the</text>\n  <text x=\"620.6666666666666\" y=\"364\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">appearance of opportunity</text>\n  <text x=\"620.6666666666666\" y=\"383\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">continuously.</text>\n  <text x=\"620.6666666666666\" y=\"420\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">The useful conclusion is to do very</text>\n  <text x=\"620.6666666666666\" y=\"439\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">little.</text>\n  <text x=\"450\" y=\"484\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">This is not market timing. It tells you which evidence has power in conditions that already exist.</text>\n  <text x=\"450\" y=\"510\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Regimes deteriorate faster than they improve, and here leverage unwinds mechanically rather than by decision.</text>\n  <text x=\"450\" y=\"534\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--diagram-muted)\">Applied to a long-term contribution schedule it becomes market timing under a more respectable name.</text>\n</svg>",
  "crypto-06-3-small-slice": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 560\" font-family=\"Arial, Helvetica, sans-serif\" role=\"img\">\n  <rect x=\"0\" y=\"0\" width=\"900\" height=\"560\" fill=\"var(--diagram-bg)\"/>\n  <text x=\"450\" y=\"34\" text-anchor=\"middle\" font-size=\"21\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Why the Allocation Is the Decision That Matters</text>\n  <text x=\"450\" y=\"57\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--diagram-muted)\">A 5% slice, a fourfold rise, and an 80% fall that is ordinary for this asset class rather than catastrophic.</text>\n  <text x=\"288\" y=\"110\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">start: crypto is 5% of the portfolio</text>\n  <rect x=\"300\" y=\"90\" width=\"91.66666666666667\" height=\"30\" rx=\"3\" fill=\"var(--success-500)\"/>\n  <text x=\"401.6666666666667\" y=\"110\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--success-text)\" font-weight=\"bold\">portfolio 100</text>\n  <text x=\"288\" y=\"156\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">after crypto rises fourfold</text>\n  <rect x=\"300\" y=\"136\" width=\"318.99999999999994\" height=\"30\" rx=\"3\" fill=\"var(--warning-500)\"/>\n  <text x=\"629\" y=\"156\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">now 17.4% — nobody chose that</text>\n  <text x=\"288\" y=\"202\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">then an 80% fall, unrebalanced</text>\n  <rect x=\"300\" y=\"182\" width=\"73.33333333333333\" height=\"30\" rx=\"3\" fill=\"var(--danger-500)\"/>\n  <text x=\"383.3333333333333\" y=\"202\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--danger-text)\" font-weight=\"bold\">portfolio 99 — essentially the whole gain returned</text>\n  <text x=\"288\" y=\"248\" text-anchor=\"end\" font-size=\"13\" fill=\"var(--diagram-text)\">rebalanced to 5% at the peak instead</text>\n  <rect x=\"300\" y=\"228\" width=\"91.66666666666667\" height=\"30\" rx=\"3\" fill=\"var(--success-500)\"/>\n  <text x=\"401.6666666666667\" y=\"248\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--success-text)\" font-weight=\"bold\">about 14 moved permanently into the rest</text>\n  <line x1=\"60\" y1=\"288\" x2=\"840\" y2=\"288\" stroke=\"var(--diagram-grid)\" stroke-width=\"1\"/>\n  <rect x=\"30\" y=\"300\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--info-500)\" stroke-width=\"2\"/>\n  <text x=\"162.66666666666666\" y=\"330\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--info-500)\" font-weight=\"bold\">Rebalancing</text>\n  <text x=\"46\" y=\"362\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Not a forecast.</text>\n  <text x=\"46\" y=\"389\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">It makes no claim that the asset</text>\n  <text x=\"46\" y=\"408\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">sold will now underperform.</text>\n  <text x=\"46\" y=\"445\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">It holds risk where you decided it</text>\n  <text x=\"46\" y=\"464\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">should be.</text>\n  <rect x=\"317.3333333333333\" y=\"300\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--warning-500)\" stroke-width=\"2\"/>\n  <text x=\"450\" y=\"330\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--warning-500)\" font-weight=\"bold\">Custody hygiene</text>\n  <text x=\"333.3333333333333\" y=\"362\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Practices decay.</text>\n  <text x=\"333.3333333333333\" y=\"389\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">Approvals accumulate. Balances creep</text>\n  <text x=\"333.3333333333333\" y=\"408\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">above the cap. Devices are replaced.</text>\n  <text x=\"333.3333333333333\" y=\"445\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">An annual hour: revoke, check,</text>\n  <text x=\"333.3333333333333\" y=\"464\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">access, verify, and tell one person.</text>\n  <rect x=\"604.6666666666666\" y=\"300\" width=\"265.3333333333333\" height=\"190\" rx=\"10\" fill=\"var(--diagram-bg)\" stroke=\"var(--success-500)\" stroke-width=\"2\"/>\n  <text x=\"737.3333333333333\" y=\"330\" text-anchor=\"middle\" font-size=\"16\" fill=\"var(--success-500)\" font-weight=\"bold\">Process review</text>\n  <text x=\"620.6666666666666\" y=\"362\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">Judge the decision, not the result.</text>\n  <text x=\"620.6666666666666\" y=\"389\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">Annual moves here are measured in</text>\n  <text x=\"620.6666666666666\" y=\"408\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-muted)\">multiples.</text>\n  <text x=\"620.6666666666666\" y=\"445\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">A reckless position can return</text>\n  <text x=\"620.6666666666666\" y=\"464\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">several hundred percent and teach</text>\n  <text x=\"620.6666666666666\" y=\"483\" text-anchor=\"start\" font-size=\"13\" fill=\"var(--diagram-text)\" font-weight=\"bold\">you nothing.</text>\n  <text x=\"450\" y=\"522\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--warning-text)\" font-weight=\"bold\">Diversification within crypto does not survive the falls, and crypto did not diversify a portfolio when it was needed.</text>\n</svg>",
});
